import 'package:flutter_test/flutter_test.dart';\nimport 'package:fintracker/helpers/db.helper.dart';\nimport 'package:fintracker/helpers/data_sanitizer.dart';\nimport 'dart:convert';\nimport 'dart:io';\n\nvoid main() {\n  group('Export Integration Tests', () {\n    setUp(() {\n      DataSanitizer.clearCache();\n    });\n\n    test('export function should create file with sanitized data when sanitize=true', () async {\n      // This test would require setting up a test database\n      // For now, we'll test the sanitization logic directly\n      \n      // Arrange\n      Map<String, dynamic> mockData = {\n        'accounts': [\n          {\n            'id': 1,\n            'name': 'John Doe Savings',\n            'holderName': 'John Doe',\n            'accountNumber': '1234567890',\n            'upiId': 'john.doe@paytm',\n            'icon': 12345,\n            'color': 0xFF4CAF50,\n            'balance': 1000.0,\n          }\n        ],\n        'payments': [\n          {\n            'Title': 'Grocery Shopping',\n            'Description': 'Weekly groceries',\n            'Amount': 150.50,\n            'Type': 'Debit',\n            'Date': '2023-12-01',\n          }\n        ],\n        'categories': [\n          {\n            'id': 1,\n            'name': 'Food & Dining',\n            'icon': 12345,\n            'color': 0xFF4CAF50,\n          }\n        ],\n        'tags': [\n          {\n            'id': 1,\n            'name': 'Personal',\n            'color': 0xFF4CAF50,\n          }\n        ]\n      };\n\n      // Act\n      Map<String, dynamic> sanitizedData = DataSanitizer.sanitizeExportData(mockData);\n\n      // Assert\n      // Verify accounts are sanitized\n      expect(sanitizedData['accounts'][0]['name'], startsWith('Account_'));\n      expect(sanitizedData['accounts'][0]['holderName'], equals('JXXXXXXe'));\n      expect(sanitizedData['accounts'][0]['accountNumber'], equals('12XXXXXX90'));\n      expect(sanitizedData['accounts'][0]['upiId'], equals('jXXXXXXe@paytm'));\n      \n      // Verify payments are sanitized\n      expect(sanitizedData['payments'][0]['Title'], startsWith('Transaction_'));\n      expect(sanitizedData['payments'][0]['Description'], startsWith('Payment description_'));\n      \n      // Verify categories are sanitized\n      expect(sanitizedData['categories'][0]['name'], startsWith('Category_'));\n      \n      // Verify tags are sanitized\n      expect(sanitizedData['tags'][0]['name'], startsWith('Tag_'));\n      \n      // Verify non-PII data is preserved\n      expect(sanitizedData['accounts'][0]['balance'], equals(1000.0));\n      expect(sanitizedData['payments'][0]['Amount'], equals(150.50));\n      expect(sanitizedData['payments'][0]['Type'], equals('Debit'));\n      expect(sanitizedData['payments'][0]['Date'], equals('2023-12-01'));\n    });\n\n    test('export function should preserve original data when sanitize=false', () async {\n      // Arrange\n      Map<String, dynamic> mockData = {\n        'accounts': [\n          {\n            'id': 1,\n            'name': 'John Doe Savings',\n            'holderName': 'John Doe',\n            'accountNumber': '1234567890',\n          }\n        ],\n        'payments': [\n          {\n            'Title': 'Grocery Shopping',\n            'Description': 'Weekly groceries',\n            'Amount': 150.50,\n          }\n        ]\n      };\n\n      // Act - no sanitization\n      Map<String, dynamic> unsanitizedData = Map<String, dynamic>.from(mockData);\n\n      // Assert - data should remain unchanged\n      expect(unsanitizedData['accounts'][0]['name'], equals('John Doe Savings'));\n      expect(unsanitizedData['accounts'][0]['holderName'], equals('John Doe'));\n      expect(unsanitizedData['accounts'][0]['accountNumber'], equals('1234567890'));\n      expect(unsanitizedData['payments'][0]['Title'], equals('Grocery Shopping'));\n      expect(unsanitizedData['payments'][0]['Description'], equals('Weekly groceries'));\n    });\n\n    test('sanitized export should not leak PII in any field', () async {\n      // Arrange\n      Map<String, dynamic> mockData = {\n        'accounts': [\n          {\n            'id': 1,\n            'name': 'John Doe Personal Account',\n            'holderName': 'John Doe',\n            'accountNumber': '1234567890123456',\n            'upiId': 'john.doe@example.com',\n          }\n        ],\n        'payments': [\n          {\n            'Title': 'Payment to John Doe for services',\n            'Description': 'Personal payment to John Doe, phone: 123-456-7890',\n            'upi_transaction_id': 'UPI123456789REAL',\n          }\n        ]\n      };\n\n      // Act\n      Map<String, dynamic> sanitizedData = DataSanitizer.sanitizeExportData(mockData);\n      String jsonOutput = jsonEncode(sanitizedData);\n\n      // Assert - no PII should be present in the output\n      expect(jsonOutput.contains('John Doe'), isFalse);\n      expect(jsonOutput.contains('1234567890123456'), isFalse);\n      expect(jsonOutput.contains('john.doe@example.com'), isFalse);\n      expect(jsonOutput.contains('123-456-7890'), isFalse);\n      expect(jsonOutput.contains('UPI123456789REAL'), isFalse);\n      \n      // But should contain sanitized versions\n      expect(jsonOutput.contains('Account_'), isTrue);\n      expect(jsonOutput.contains('Transaction_'), isTrue);\n      expect(jsonOutput.contains('TXN'), isTrue);\n    });\n\n    test('sanitization should be consistent across multiple calls', () async {\n      // Arrange\n      Map<String, dynamic> mockData = {\n        'accounts': [\n          {\n            'id': 1,\n            'name': 'Test Account',\n            'holderName': 'Test User',\n          }\n        ]\n      };\n\n      // Act\n      Map<String, dynamic> sanitized1 = DataSanitizer.sanitizeExportData(mockData);\n      Map<String, dynamic> sanitized2 = DataSanitizer.sanitizeExportData(mockData);\n\n      // Assert\n      expect(sanitized1['accounts'][0]['name'], equals(sanitized2['accounts'][0]['name']));\n      expect(sanitized1['accounts'][0]['holderName'], equals(sanitized2['accounts'][0]['holderName']));\n    });\n  });\n}